pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address nonOwner, address newOwner) public {
        // Ensure nonOwner is not the current owner
        address currentOwner = c.owner();
        vm.assume(nonOwner != currentOwner);
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != currentOwner);

        vm.prank(currentOwner);
        // Initialize via grantAllowances which is onlyOwner so it sets the initial owner
        // but we need a proper initialization. Actually c.owner() is 0 initially.
        // The test harness deploys C with 'new C()' but the contract is not initialized.
        // We can't call initialize because it's onlyInitializing and also requires specific setup.
        // Since the property is about transferOwnership we just prank as the current owner (zero address initially).
        // Actually the fuzzer can call transferOwnership from any address.
        // We check the owner before and after.

        address ownerBefore = c.owner();
        vm.prank(nonOwner);
        bool success = false;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }
        address ownerAfter = c.owner();

        // The correct contract reverts for non-owner, so owner stays same.
        // The buggy contract does not revert, so owner changes to newOwner.
        // The property: if caller is non-owner, either call reverts OR owner stays same.
        // Exactly: ownerAfter != ownerBefore implies the caller was the previous owner.
        // So: (caller == ownerBefore) || (ownerAfter == ownerBefore)
        assertTrue((nonOwner == ownerBefore) || (ownerAfter == ownerBefore));
    }
}

