contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // initialize with dummy addresses to avoid zero address issues during setup
        // we need to cheat the initializer, use address(this) for all dependencies for simplicity
        c.initialize(
            IERC20(address(this)),
            IERC20(address(this)),
            IRewardRouterV2(address(this)),
            IGlpManager(address(this)),
            address(this),
            address(this)
        );
        // wire up the keeper to be able to call pauseDeposit
        c.setKeeper(address(this));
    }
    function testFuzz_property(bool shouldPause) public {
        // We want to test that paused() reflects the actual pause state.
        // The reference correctly returns true after pauseDeposit, false after unpauseDeposit.
        // The bug always returns false regardless of pause state.
        if (shouldPause) {
            c.pauseDeposit();
        } else {
            // ensure we start unpaused; if already unpaused, calling pauseDeposit and then unpauseDeposit
            // we simplify: just ensure we can call unpauseDeposit if it's paused, but since we can't directly
            // unpause without being paused, we first pause then unpause to force unpaused state.
            // But the test should work regardless: the bug always returns false.
            c.pauseDeposit();
            c.unpauseDeposit();
        }
        bool isPaused = c.paused();
        // The general rule: paused() returns true if and only if the contract is in a paused state.
        // After pauseDeposit, it should be true; after unpauseDeposit, false.
        // The bug breaks this by always returning false.
