pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 newThreshold) public {
        // Admissible domain: caller is not the zero address (owner can be zero after renounce, but we want a non-owner)
        vm.assume(caller != address(0));
        // Ensure the caller is NOT the current owner
        vm.assume(caller != c.owner());
        // Bound the new threshold to a reasonable range to avoid overflow issues (keep wide)
        newThreshold = bound(newThreshold, 0, 10000);

        // Record the threshold before the call
        uint256 thresholdBefore = c.slippageThresholdGmxBps();

        // Drive the call as the non-owner
        vm.prank(caller);
        bool ok = true;
        try c.setThresholds(newThreshold) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, read the actual threshold
        uint256 thresholdAfter = c.slippageThresholdGmxBps();

        // General rule: either the call reverted (ok == false) OR the threshold remained unchanged.
        // The bug breaks this by allowing a non-owner to change the threshold without revert.
        assertTrue(!ok || thresholdAfter == thresholdBefore);
    }
}

