pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 threshold, address actor) public {
        // Restrict the threshold to a reasonable range to keep the domain wide but admissible
        bound(threshold, 0, 10_000);

        // Ensure the actor is the owner to attempt a legitimate call
        vm.assume(actor == c.owner());

        // Attempt to set the threshold using a pranked call
        vm.prank(actor);
        try c.setThresholds(threshold) {
            // If the call succeeds, the state variable should be updated
            assertEq(c.slippageThresholdGmxBps(), threshold, "Reference: threshold should be updated on success");
        } catch {
            // If the call fails, assert that the state variable remains unchanged
            // For the reference contract, this catch block may not be exercised for the owner,
            // but the buggy version will always revert, so it will land here.
            // The assertion below will fail for the buggy version because the owner call should succeed.
            uint256 current = c.slippageThresholdGmxBps();
            // The buggy version always reverts, so the threshold never equals the input.
            // We assert that the current value must equal the input if the call succeeded (which it didn't here),
            // so this assertion will fail for the buggy version when the owner calls (since it reverts unexpectedly).
            assertEq(current, threshold, "Buggy: threshold should equal input on owner call");
        }
    }
}

