        vm.prank(caller);
        bool ok;
        try c.setThresholds(threshold) { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(c.slippageThresholdGmxBps() == threshold);
        } else {
            // If it reverts, we check nothing about slippageThresholdGmxBps equality.
